library(tidyverse)
library(GGally)

# Root directory containing parameter_estimation, result_evaluation, and simulate_responses.
setwd("/root/path")

theta_dir <- "simulate_responses/params_pyirt_metabench"
# Generated by simulate_responses/generate_responses.py; not included due to size.
response_dir <- "analysis"
out_file <- "theta_ranking_recovery_factors.csv"




# ----- Get characteristics of the data-generating thetas and itempars ---------------------

benchmarks <- c(
  "truthfulqa",
  "arc",
  "winogrande",
  "gsm8k",
  "hellaswag",
  "mmlu"
)

irts <- c("1pl", "2pl", "3pl")

theta_grid <- seq(-6, 6, by = 0.02)
log_prior <- dnorm(theta_grid, mean = 0, sd = 3, log = TRUE)

results <- list()


for (benchmark in benchmarks) {
  for (irt in irts) {
    true_theta <- read_csv(
      file.path(theta_dir, benchmark, irt, "theta.csv"),
      show_col_types = FALSE
    )$theta

    item_parameters <- read_csv(
      file.path(theta_dir, benchmark, irt, "itempars.csv"),
      show_col_types = FALSE
    )

    response_df <- read.csv(
      file.path(
        response_dir,
        benchmark,
        irt,
        "resp_sim_rep1.csv"
      ),
      check.names = FALSE
    )

    item_names <- as.character(item_parameters$itemid)
    response <- as.matrix(
      response_df[, item_names, drop = FALSE]
    )

    rm(response_df)
    gc()


    # Bias-corrected moment sample skewness.
    n_models <- length(true_theta)

    moment_skewness <- mean(
      (true_theta - mean(true_theta))^3
    ) / mean(
      (true_theta - mean(true_theta))^2
    )^(3 / 2)

    theta_skewness <- (
      sqrt(n_models * (n_models - 1)) /
        (n_models - 2)
    ) * moment_skewness


    # Marginal reliability from the posterior distribution of theta.
    eta <- item_parameters$a *
      t(outer(theta_grid, item_parameters$b, "-"))

    probability <- item_parameters$c +
      (1 - item_parameters$c) * plogis(eta)

    probability <- pmin(pmax(probability, 1e-12), 1 - 1e-12)

    log_probability_incorrect <- log(1 - probability)
    log_probability_ratio <- log(probability) - log_probability_incorrect

    log_likelihood <- t(response %*% log_probability_ratio) + colSums(log_probability_incorrect)
    log_posterior <- log_likelihood + log_prior
    largest_log_posterior <- apply(log_posterior, 2, max)
    log_posterior <- log_posterior -
      rep(largest_log_posterior, each = length(theta_grid))

    post_prob <- exp(log_posterior)
    post_prob <- post_prob /
      rep(colSums(post_prob), each = length(theta_grid))

    theta_eap <- as.vector(
      theta_grid %*% post_prob
    )

    post_second_moment <- as.vector(
      (theta_grid^2) %*% post_prob
    )

    post_var <- post_second_moment - theta_eap^2

    marginal_reliability <- var(theta_eap) /
      (var(theta_eap) + mean(post_var))


    # Rescale theta to mean 0 and SD 1 while preserving a(theta - b).
    theta_mean <- mean(true_theta)
    theta_sd <- sd(true_theta)

    theta_scaled <- (true_theta - theta_mean) / theta_sd
    b_scaled <- (item_parameters$b - theta_mean) / theta_sd
    a_scaled <- item_parameters$a * theta_sd

    sorted_b <- sort(b_scaled)

    nearby_item_count <- findInterval(theta_scaled + 0.2, sorted_b) - 
      findInterval(theta_scaled - 0.2, sorted_b)

    insufficient_coverage <- mean(nearby_item_count < 5)
    median_a <- median(a_scaled)


    results[[length(results) + 1]] <- tibble(
      benchmark = benchmark,
      irt = irt,
      n_models = n_models,
      n_items = nrow(item_parameters),
      theta_skewness = theta_skewness,
      marginal_reliability = marginal_reliability,
      insufficient_coverage = insufficient_coverage,
      median_a = median_a
    )

    write_csv(
      bind_rows(results),
      out_file
    )

    rm(
      true_theta,
      item_parameters,
      response,
      eta,
      probability,
      log_probability_incorrect,
      log_probability_ratio,
      log_likelihood,
      log_posterior,
      largest_log_posterior,
      post_prob,
      theta_eap,
      post_second_moment,
      post_var,
      theta_scaled,
      b_scaled,
      a_scaled,
      sorted_b,
      nearby_item_count
    )
    gc()

    message(paste(benchmark, irt, sep = " | "))
  }
}


