# ------ multilevel regression model ------------------------------------
# fisher transform kendall's tau for theta ranking

library(lme4)

# Standardize condition characteristics across the 18 benchmark x IRT conditions.
factor_model_df <- factor_df %>%
  mutate(
    absolute_theta_skewness = abs(theta_skewness),
    absolute_theta_skewness_z = as.numeric(scale(absolute_theta_skewness)),
    insufficient_coverage_z = as.numeric(scale(insufficient_coverage)),
    marginal_reliability_z = as.numeric(scale(marginal_reliability))
  )

sample_sizes <- c(30, 100, 180, 400, 1000)
mean_log_n <- mean(log(sample_sizes))
sd_log_n <- sd(log(sample_sizes))

# run_df.csv is generated by result_evaluation/code/Result_summary.Rmd.
run_df_params <- read_csv(
  "result_evaluation/summary_table_all_runs/run_df.csv",
  show_col_types = FALSE
) %>%
  filter(
    exit_status == TRUE,
    is.na(failure_warning_combined)
  )

model_df <- run_df_params %>%
  mutate(
    benchmark = recode(
      benchmark,
      "TruthfulQA" = "truthfulqa",
      "ARC-Challenge" = "arc",
      "WinoGrande" = "winogrande",
      "GSM8K" = "gsm8k",
      "HellaSwag" = "hellaswag",
      "MMLU" = "mmlu"
    )
  ) %>%
  filter(!is.na(cor_theta_kendall)) %>%
  dplyr::select(
    benchmark,
    irt,
    sample_size,
    rep,
    method,
    cor_theta_kendall
  ) %>%
  left_join(factor_model_df, by = c("benchmark", "irt")) %>%
  mutate(
    tau_for_model = pmin(pmax(cor_theta_kendall, -0.9999), 0.9999),
    z_tau = atanh(tau_for_model),
    log_n_z = (log(sample_size) - mean_log_n) / sd_log_n,
    method = factor(method, levels = c("EM", "MCMC", "VI", "PSN")),
    condition = interaction(benchmark, irt, drop = TRUE),
    condition_rep = interaction(condition, rep, drop = TRUE)
  )

# Compare each estimation method with the grand mean across methods.
method_contrasts <- contr.sum(4)
colnames(method_contrasts) <- c("EM", "MCMC", "VI")
contrasts(model_df$method) <- method_contrasts


ranking_model <- lmer(
  z_tau ~
    log_n_z +
    method +
    absolute_theta_skewness_z +
    insufficient_coverage_z +
    marginal_reliability_z +
    (1 | condition) +
    (1 | condition_rep),
  data = model_df,
  REML = FALSE
)

# Jackknife standard errors (leave one condition out at a time)
conditions <- levels(model_df$condition)
jackknife_estimates <- vector("list", length(conditions))

for (i in seq_along(conditions)) {
  condition_left_out <- conditions[i]

  jackknife_data <- model_df %>%
    filter(condition != condition_left_out) %>%
    mutate(
      condition = droplevels(condition),
      condition_rep = droplevels(condition_rep)
    )

  jackknife_model <- update(
    ranking_model,
    data = jackknife_data
  )

  jackknife_fixed_effects <- fixef(jackknife_model)
  jackknife_fixed_effects["methodPSN"] <- -sum(
    jackknife_fixed_effects[c("methodEM", "methodMCMC", "methodVI")]
  )

  jackknife_estimates[[i]] <- tibble(
    term = names(jackknife_fixed_effects),
    estimate = unname(jackknife_fixed_effects)
  )
}

jackknife_estimates <- bind_rows(jackknife_estimates)

full_fixed_effects <- fixef(ranking_model)
full_fixed_effects["methodPSN"] <- -sum(
  full_fixed_effects[c("methodEM", "methodMCMC", "methodVI")]
)

full_estimates <- tibble(
  term = names(full_fixed_effects),
  full_estimate = unname(full_fixed_effects)
)

n_conditions <- length(conditions)

jackknife_summary <- jackknife_estimates %>%
  left_join(full_estimates, by = "term") %>%
  group_by(term, full_estimate) %>%
  summarise(
    jackknife_se = sqrt(
      (n_conditions - 1) / n_conditions *
        sum((estimate - mean(estimate))^2)
    ),
    .groups = "drop"
  ) %>%
  mutate(
    ci_lower = full_estimate -
      qt(0.975, df = n_conditions - 1) * jackknife_se,
    ci_upper = full_estimate +
      qt(0.975, df = n_conditions - 1) * jackknife_se
  ) %>%
  dplyr::select(
    term,
    full_estimate,
    jackknife_se,
    ci_lower,
    ci_upper
  )

# Markdown table of fixed effects with jackknife uncertainty
jackknife_markdown_table <- jackknife_summary %>%
  mutate(
    term = recode(
      term,
      "(Intercept)" = "Intercept",
      "log_n_z" = "Log sample size",
      "methodEM" = "MML-EM vs. method grand mean",
      "methodMCMC" = "MCMC vs. method grand mean",
      "methodVI" = "VI vs. method grand mean",
      "methodPSN" = "PSN vs. method grand mean",
      "absolute_theta_skewness_z" = "Absolute theta skewness",
      "insufficient_coverage_z" = "Insufficient item coverage",
      "marginal_reliability_z" = "Marginal reliability"
    )
  ) %>%
  transmute(
    Predictor = term,
    Estimate = round(full_estimate, 3),
    `Jackknife SE` = round(jackknife_se, 3),
    `95% t-CI` = sprintf("[%.3f, %.3f]", ci_lower, ci_upper)
  )

knitr::kable(
  jackknife_markdown_table,
  format = "pipe",
  align = c("l", "r", "r", "c")
)


# Total relevance: add each condition characteristic to the control model alone.
control_model <- update(
  ranking_model,
  . ~ . -
    absolute_theta_skewness_z -
    insufficient_coverage_z -
    marginal_reliability_z
)

skewness_model <- update(
  control_model,
  . ~ . + absolute_theta_skewness_z
)

coverage_model <- update(
  control_model,
  . ~ . + insufficient_coverage_z
)

reliability_model <- update(
  control_model,
  . ~ . + marginal_reliability_z
)

control_r2 <- performance::r2_nakagawa(control_model)$R2_marginal
skewness_r2 <- performance::r2_nakagawa(skewness_model)$R2_marginal
coverage_r2 <- performance::r2_nakagawa(coverage_model)$R2_marginal
reliability_r2 <- performance::r2_nakagawa(reliability_model)$R2_marginal

total_relevance_table <- tibble(
  Model = c(
    "Method and sample size only",
    "Add absolute theta skewness",
    "Add insufficient item coverage",
    "Add marginal reliability"
  ),
  `Marginal R2` = c(
    control_r2,
    skewness_r2,
    coverage_r2,
    reliability_r2
  )
) %>%
  mutate(
    `Increase from control model` = `Marginal R2` - control_r2,
    across(where(is.numeric), ~ round(.x, 3))
  )

knitr::kable(
  total_relevance_table,
  format = "pipe",
  align = c("l", "r", "r")
)
